create table if not exists circle_private.learning_catalog(
 chapter_no integer primary key,term_ids text[] not null,answers text[] not null
);
revoke all on circle_private.learning_catalog from public,anon,authenticated;
insert into circle_private.learning_catalog values
-- CATALOG_ROWS
on conflict(chapter_no) do update set term_ids=excluded.term_ids,answers=excluded.answers;
create table if not exists public.circle_learning_progress(
 user_id uuid not null references auth.users on delete cascade,
 chapter_no integer not null check(chapter_no between 1 and 10),
 reviewed_terms text[] not null default '{}',completed_at timestamptz,
 updated_at timestamptz not null default now(),primary key(user_id,chapter_no)
);
alter table public.circle_learning_progress enable row level security;
revoke all on public.circle_learning_progress from public,anon,authenticated;
